import { ForbiddenException } from "@nestjs/common";

import { MyGlobal } from "../../MyGlobal";
import { jwtAuthorize } from "./jwtAuthorize";
import { CustomerPayload } from "../../decorators/payload/CustomerPayload";

/**
 * Authenticate and authorize a customer.
 *
 * @param request - The HTTP request object containing headers.
 * @returns The authenticated CustomerPayload.
 * @throws ForbiddenException if authentication fails or customer is not valid.
 */
export async function customerAuthorize(request: {
  headers: {
    authorization?: string;
  };
}): Promise<CustomerPayload> {
  const payload: CustomerPayload = jwtAuthorize({ request }) as CustomerPayload;

  if (payload.type !== "customer") {
    throw new ForbiddenException(`You're not ${payload.type}`);
  }

  // Find only valid/active customers by their id and business status
  const customer = await MyGlobal.prisma.shopping_mall_ai_customers.findFirst({
    where: {
      id: payload.id,
      deleted_at: null,
      status: "active"
    }
  });

  if (customer === null) {
    throw new ForbiddenException("You're not enrolled");
  }

  return payload;
}

