import { ForbiddenException } from "@nestjs/common";

import { MyGlobal } from "../../MyGlobal";
import { jwtAuthorize } from "./jwtAuthorize";
import { SellerPayload } from "../../decorators/payload/SellerPayload";

/**
 * Authenticate and authorize a seller.
 *
 * - Verifies JWT using the jwtAuthorize function
 * - Checks payload.type is "seller"
 * - Looks up seller in shopping_mall_ai_sellers, enforcing validation/active status
 * - Throws ForbiddenException if not valid
 *
 * @param request Express request object
 * @returns SellerPayload for the authenticated seller
 */
export async function sellerAuthorize(request: {
  headers: {
    authorization?: string;
  };
}): Promise<SellerPayload> {
  const payload: SellerPayload = jwtAuthorize({ request }) as SellerPayload;

  if (payload.type !== "seller") {
    throw new ForbiddenException(`You're not ${payload.type}`);
  }

  // Validate seller existence, status, and approval
  const seller = await MyGlobal.prisma.shopping_mall_ai_sellers.findFirst({
    where: {
      id: payload.id,
      deleted_at: null,
      status: "active",
      is_verified: true,
    },
  });

  if (seller === null) {
    throw new ForbiddenException("You're not enrolled or approved.");
  }

  return payload;
}

