import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe"
import { IAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IAttachment";


/**
 * 업데이트: 첨부파일 버전 메타데이터 갱신 엔드포인트
 *
 * 이 엔드포인트는 shopping_mall_ai_attachment_versions 테이블의 특정 첨부파일 버전 레코드의 diff_comment(변경 주석) 또는 삭제 플래그(deleted)를 업데이트합니다. 실제 파일 컨텐츠 변경 없이, 준법/감사 목적으로 버전 주석 또는 상태를 수정합니다. diff_comment, deleted 필드만 업데이트 가능하며, 그 외 버전의 메타/파일 속성은 불변입니다.
 *
 * 관리자 권한이 필요하며, 기록의 체인-오브-커스터디 보호를 위해 불필요한 변경은 방지되어야 합니다. (단, 인증 체크는 별도 미포함.)
 *
 * @param props - 요청 파라미터 및 바디
 * @param props.attachmentId - 첨부파일 식별자(UUID)
 * @param props.attachmentVersionId - 첨부파일 버전 식별자(UUID)
 * @param props.body - diff_comment, deleted 등 변경할 메타데이터 필드 (선택적)
 * @returns 업데이트된 첨부파일 버전 상세 (IAttachment.AttachmentVersion)
 * @throws {Error} 첨부파일 버전이 존재하지 않을 때 발생
 */
export async function put__shoppingMallAi_administrator_attachments_$attachmentId_attachmentVersions_$attachmentVersionId(
    props: {
        attachmentId: string & tags.Format<'uuid'>;
        attachmentVersionId: string & tags.Format<'uuid'>;
        body: IAttachment.AttachmentVersion.IUpdate;
    }
): Promise<IAttachment.AttachmentVersion> {
    const { attachmentVersionId, body } = props;
    // 1. 존재 확인 (불변 필드는 반환/응답에 필요)
    const base = await MyGlobal.prisma.shopping_mall_ai_attachment_versions.findUnique({
        where: { id: attachmentVersionId },
    });
    if (!base) throw new Error('Attachment version not found');
    // 2. 업데이트 대상 필드 선정 (둘 다 undefined/null이면 update하지 않고 불변값 반환)
    const updateData: Partial<Pick<typeof body, 'diff_comment' | 'deleted'>> = {};
    if (body.diff_comment !== undefined) updateData.diff_comment = body.diff_comment;
    if (body.deleted !== undefined && body.deleted !== null) updateData.deleted = body.deleted;
    let updated = base;
    if (Object.keys(updateData).length > 0) {
        updated = await MyGlobal.prisma.shopping_mall_ai_attachment_versions.update({
            where: { id: attachmentVersionId },
            data: updateData,
        });
    }
    // 3. 반환 DTO 포맷에 맞춰 정제
    return {
        id: updated.id,
        attachment_id: updated.attachment_id,
        modified_by_id: updated.modified_by_id,
        version_number: updated.version_number,
        file_uri: updated.file_uri,
        file_size: updated.file_size,
        created_at: toISOStringSafe(updated.created_at),
        diff_comment: updated.diff_comment ?? null,
        deleted: updated.deleted,
    };
}

