  props: { attachmentId: string & tags.Format<'uuid'> }
): Promise<void> {
  const { attachmentId } = props;
  // Fetch the attachment by primary key
  const attachment = await MyGlobal.prisma.shopping_mall_ai_attachments.findUniqueOrThrow({
    where: { id: attachmentId },
    select: {
      id: true,
      deleted: true,
      legal_hold: true,
    },
  });

  // If the attachment is already deleted, block further soft-deletion
  if (attachment.deleted) {
    throw new Error('Attachment already deleted');
  }

  // If the attachment is under legal hold, deletion is not permitted
  if (attachment.legal_hold) {
    throw new Error('Attachment is under legal hold and cannot be deleted');
  }

  // Perform soft-delete: set deleted=true and deleted_at=now
  await MyGlobal.prisma.shopping_mall_ai_attachments.update({
    where: { id: attachmentId },
    data: {
      deleted: true,
      deleted_at: toISOStringSafe(new Date()),
    },
  });
}

