/**
 * Authenticate a customer using email and password. Issues a JWT token using shopping_mall_ai_customers fields.
 *
 * This operation verifies the customer's credentials (email and password) by searching for an active, non-deleted customer record.
 * On successful authentication, it issues a signed JWT for subsequent API calls, and sets last_login_at.
 *
 * @param props - Request parameters
 * @param props.body - Customer login credentials to authenticate
 * @returns Authentication result including JWT Authorization token and customer metadata
 * @throws {Error} When email/password combination does not match any active customer, or account is not active
 */
export async function post__auth_customer_login(
  props: { body: IShoppingMallAiCustomer.SignIn }
): Promise<IShoppingMallAiCustomer.AuthResult> {
  const { email, password } = props.body;

  // 1. Find customer with matching email and not soft-deleted
  const customer = await MyGlobal.prisma.shopping_mall_ai_customers.findFirst({
    where: { email, deleted_at: null },
  });

  // If customer not found or not active, respond with generic error
  if (!customer || customer.status !== "active") {
    throw new Error("Invalid credentials");
  }

  // 2. Verify the password using browser-safe crypto (Web Crypto API PBKDF2 or similar)
  // This MUST be implemented safely in browser-compatible way
  const validPassword = await checkPassword(password, customer.password_hash);
  if (!validPassword) {
    throw new Error("Invalid credentials");
  }

  // 3. Issue signed JWT for this customer (browser-compatible, e.g., Web Crypto API)
  // sub = customer.id, role = customer
  const jwt = await signJWT({
    sub: customer.id,
    role: "customer",
    iat: Math.floor(Date.now() / 1000),
  });

  // 4. Set last_login_at to now (ISO string)
  const now = toISOStringSafe(new Date());
  await MyGlobal.prisma.shopping_mall_ai_customers.update({
    where: { id: customer.id },
    data: { last_login_at: now },
  });

  // 5. Return AuthResult as required by API
  return {
    setHeaders: { Authorization: `Bearer ${jwt}` },
    id: customer.id,
    email: customer.email,
    nickname: customer.nickname,
    status: customer.status,
    is_email_verified: customer.is_email_verified,
    is_mobile_verified: customer.is_mobile_verified,
    last_login_at: customer.last_login_at ? toISOStringSafe(customer.last_login_at) : null,
    created_at: toISOStringSafe(customer.created_at),
    updated_at: toISOStringSafe(customer.updated_at),
  };
}

