/**
 * Soft-delete an attachment version (Attachment schema) for compliance/audit.
 *
 * Soft-deletes (flags as deleted) a specific attachment version in the shopping_mall_ai_attachment_versions table. This preserves the record for legal and audit purposes, ensures downstream systems omit the deleted version, and enforces legal hold compliance. Fails if the version is already deleted, does not exist, or if the parent attachment is under legal hold.
 *
 * @param props - Request properties
 * @param props.attachmentId - Attachment unique identifier, references shopping_mall_ai_attachments.id
 * @param props.attachmentVersionId - Attachment version unique identifier, references shopping_mall_ai_attachment_versions.id
 * @returns void
 * @throws {Error} Attachment version not found
 * @throws {Error} Attachment version already deleted
 * @throws {Error} Attachment not found
 * @throws {Error} Cannot delete: attachment is under legal hold
 */
export async function delete__shoppingMallAi_administrator_attachments_$attachmentId_attachmentVersions_$attachmentVersionId(
  props: {
    attachmentId: string & tags.Format<'uuid'>;
    attachmentVersionId: string & tags.Format<'uuid'>;
  }
): Promise<void> {
  const { attachmentId, attachmentVersionId } = props;
  // 1. Find the attachment version (must match attachment_id and not already deleted)
  const version = await MyGlobal.prisma.shopping_mall_ai_attachment_versions.findUnique({
    where: { id: attachmentVersionId },
    select: { id: true, attachment_id: true, deleted: true, deleted_at: true }
  });
  if (!version) throw new Error("Attachment version not found");
  if (version.attachment_id !== attachmentId) throw new Error("Version does not belong to the specified attachment");
  if (version.deleted) throw new Error("Attachment version already deleted");

  // 2. Find the parent attachment
  const attachment = await MyGlobal.prisma.shopping_mall_ai_attachments.findUnique({
    where: { id: version.attachment_id },
    select: { id: true, legal_hold: true }
  });
  if (!attachment) throw new Error("Attachment not found");
  if (attachment.legal_hold) throw new Error("Cannot delete: attachment is under legal hold");

  // 3. Perform soft delete
  await MyGlobal.prisma.shopping_mall_ai_attachment_versions.update({
    where: { id: attachmentVersionId },
    data: {
      deleted: true,
      deleted_at: toISOStringSafe(new Date())
    }
  });
  // Optionally, audit log action here
}

