    body: IAttachment.AttachmentBusinessLink.IRequest;
  }
): Promise<IPageIAttachment.AttachmentBusinessLink> {
  const { attachmentId, body } = props;
  const page = (body.page && body.page > 0) ? body.page : 1;
  const limit = (body.limit && body.limit > 0) ? body.limit : 20;

  // Build filters for Prisma, only include properties if not undefined/null
  const where = {
