/**
 * Register a new seller account (shopping_mall_ai_sellers) and issue JWT tokens.
 *
 * This endpoint allows a new seller to securely register on the shoppingMallAi platform, enforcing uniqueness of both email and business registration number. On success, a JWT token is returned for authenticated API use, placed in the 'setHeaders' field. Strict data, security, and business onboarding rules apply.
 *
 * @param props - The registration request containing seller onboarding fields.
 * @param props.body - Registration data: email, password, display_name, business_registration_number.
 * @returns The new seller profile and JWT setHeaders for session authentication.
 * @throws {Error} If email or business registration number is already registered.
 * @throws {Error} If browser crypto.subtle is unavailable.
 */
export async function post__auth_seller_register(props: { body: ISellerAuthRegisterRequest }): Promise<ISellerAuthWithSetHeaders> {
  const { body } = props;

  // 1. Enforce uniqueness for email and business registration number
  const duplicate = await MyGlobal.prisma.shopping_mall_ai_sellers.findFirst({
    where: {
      OR: [
        { email: body.email },
        { business_registration_number: body.business_registration_number },
      ],
    },
  });
  if (duplicate) {
    throw new Error('Email or business registration number already registered');
  }

  // 2. Hash password using browser-compatible SubtleCrypto (SHA-256, base64url)
  if (!(typeof window !== 'undefined' && window.crypto && window.crypto.subtle)) {
    throw new Error('Browser-compatible crypto.subtle is required for password hashing');
  }
  const encoder = new TextEncoder();
  const passwordUint8 = encoder.encode(body.password);
  const pwBuffer = await window.crypto.subtle.digest('SHA-256', passwordUint8);
  const password_hash = btoa(String.fromCharCode(...new Uint8Array(pwBuffer)));

  // 3. Seller record creation (schema-verified fields only; all date fields as ISO string)
  const now = toISOStringSafe(new Date());
  const created = await MyGlobal.prisma.shopping_mall_ai_sellers.create({
    data: {
      id: v4() as string & tags.Format<'uuid'>,
      email: body.email,
      password_hash,
      display_name: body.display_name,
      business_registration_number: body.business_registration_number,
      status: 'active',
      is_verified: false,
      business_name: body.display_name,
      created_at: now,
      updated_at: now,
    },
  });

  // 4. Generate browser-safe JWT token
  const header = { alg: 'HS256', typ: 'JWT' };
  const payload = {
    sub: created.id,
    email: created.email,
    role: 'seller',
    exp: Math.floor(Date.now() / 1000) + 60 * 60 * 24,
  };
  function base64url(val: string) {
    return btoa(val).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
  }
  const sHeader = base64url(JSON.stringify(header));
  const sPayload = base64url(JSON.stringify(payload));
  const secret = encoder.encode('AUTO_BE_JWT_SECRET');
  const message = encoder.encode(`${sHeader}.${sPayload}`);
  const key = await window.crypto.subtle.importKey(
    'raw',
    secret,
    { name: 'HMAC', hash: 'SHA-256' },
    false,
    ['sign']
  );
  const sigBuf = await window.crypto.subtle.sign('HMAC', key, message);
  const sig = base64url(String.fromCharCode(...new Uint8Array(sigBuf)));
  const jwt = `${sHeader}.${sPayload}.${sig}`;

  // 5. Return seller info and Authorization header
  return {
    seller: {
      id: created.id,
      email: created.email,
      display_name: created.display_name,
      business_registration_number: created.business_registration_number,
      status: created.status,
      is_verified: created.is_verified,
    },
    setHeaders: { Authorization: `Bearer ${jwt}` },
  };
}

