/**
 * Search, filter, and paginate all file attachments in the platform with advanced ACL and legal/compliance filtering.
 *
 * Retrieve a paginated, filtered list of attachments uploaded to the shoppingMallAi platform. This operation interfaces directly with the shopping_mall_ai_attachments table, exposing metadata and business context — such as file name, MIME type, business domain (product image, evidence, invoice, etc.), retention policy, uploader, and access control settings.
 *
 * Pagination options support efficient handling of large file volumes, while advanced filter criteria enable searches by filename, uploader, creation period, legal hold status, deletion flag, retention policy, or business domain. Attachments under legal hold, or flagged for compliance, are only shown to those with authorized roles (administrator or specifically allowed business roles).
 *
 * Security enforcement is based on the user's permission scope, as mapped by ACL in the attachments table and backed by the role-based permissions matrix. Users may only see and access files relevant to their business function. Non-authorized access attempts are denied and logged. This endpoint forms the cornerstone of all file management workflows within the system, supporting evidence preservation, compliance audits, and multi-domain asset discovery. Use with caution in compliance/restricted views.
 *
 * @param props - Request properties
 * @param props.body - Attachment listing and filter/search criteria (pagination, uploader, domain, retention, legal compliance, etc.)
 * @returns A page of attachment summary details, matching search, filter, and role-based access criteria
 * @throws {Error} When access restrictions apply or internal errors occur
 */
export async function patch__shoppingMallAi_administrator_attachments(
  props: { body: IShoppingMallAiAttachment.IRequest },
): Promise<IPageIShoppingMallAiAttachment.ISummary> {
  const { body } = props;

  // Pagination, defaulting
  const page = body.page;
  const limit = Math.min(body.limit, 100);
  const skip = (page - 1) * limit;

  // Sorting
  let sortField = "created_at" as const;
  let sortOrder: "asc" | "desc" = "desc";
  if (body.sort) {
    const [field, order] = body.sort.split(":");
    if (["created_at", "filename", "file_size"].includes(field)) {
      sortField = field as typeof sortField;
      sortOrder = order === "asc" ? "asc" : "desc";
    }
  }

  // Prisma where condition
  const where = {
    ...(body.filename !== undefined && body.filename !== null && {
      filename: { contains: body.filename, mode: "insensitive" as const },
    }),
    ...(body.mime_type !== undefined && body.mime_type !== null && {
      mime_type: body.mime_type,
    }),
    ...(body.business_domain !== undefined && body.business_domain !== null && {
      business_domain: body.business_domain,
    }),
    ...(body.retention_policy_code !== undefined && body.retention_policy_code !== null && {
      retention_policy_code: body.retention_policy_code,
    }),
    ...(body.uploader_id !== undefined && body.uploader_id !== null && {
      uploaded_by_id: body.uploader_id,
    }),
    ...(body.legal_hold !== undefined && body.legal_hold !== null && {
      legal_hold: body.legal_hold,
    }),
    ...(body.deleted !== undefined && body.deleted !== null && {
      deleted: body.deleted,
    }),
    ...(body.is_active !== undefined && body.is_active !== null
      ? { deleted: !body.is_active }
      : {}),
    ...((body.created_from !== undefined && body.created_from !== null) || (body.created_to !== undefined && body.created_to !== null)
      ? {
          created_at: {
            ...(body.created_from !== undefined && body.created_from !== null && { gte: body.created_from }),
            ...(body.created_to !== undefined && body.created_to !== null && { lte: body.created_to }),
          },
        }
      : {}),
  };

  // Query DB & total count concurrently
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_attachments.findMany({
      where,
      orderBy: { [sortField]: sortOrder },
      skip,
      take: limit,
      select: {
        id: true,
        filename: true,
        mime_type: true,
        file_size: true,
        business_domain: true,
        retention_policy_code: true,
        legal_hold: true,
        deleted: true,
        uploaded_by_id: true,
        created_at: true,
      },
    }),
    MyGlobal.prisma.shopping_mall_ai_attachments.count({ where }),
  ]);

  const pages = Math.max(1, Math.ceil(total / limit));

  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: pages,
    },
    data: rows.map((row) => ({
      id: row.id as string & tags.Format<"uuid">,
      filename: row.filename,
      mime_type: row.mime_type,
      file_size: row.file_size,
      business_domain: row.business_domain,
      retention_policy_code: row.retention_policy_code,
      legal_hold: row.legal_hold,
      deleted: row.deleted,
      uploaded_by_id: row.uploaded_by_id as string & tags.Format<"uuid">,
      created_at: toISOStringSafe(row.created_at),
    })),
  };
}

