/**
 * Soft-delete an attachment version (Attachment schema) for compliance/audit.
 *
 * Soft-deletes an attachment version by setting its 'deleted' flag in the shopping_mall_ai_attachment_versions table.
 * This operation is critical for compliance, legal requests (such as GDPR or evidence redaction), or to flag superseded or problematic file versions.
 * While the record is not physically deleted to ensure auditability and historical traceability, the deleted flag is updated and version availability is restricted in user-facing experiences.
 *
 * Only administrators or actors with explicit privilege can perform this action. Deletion is not permitted if the attachment is subject to a legal hold, or if the version is already deleted.
 * All such actions must be logged to an immutable audit trail for incident review.
 *
 * @param props - Request properties
 * @param props.attachmentId - Attachment unique identifier, references shopping_mall_ai_attachments.id
 * @param props.attachmentVersionId - Attachment version unique identifier, references shopping_mall_ai_attachment_versions.id
 * @returns void
 * @throws {Error} When the attachment version does not exist
 * @throws {Error} When the attachment version is already deleted
 * @throws {Error} When the parent attachment is under legal hold
 */
export async function delete__shoppingMallAi_administrator_attachments_$attachmentId_attachmentVersions_$attachmentVersionId(props: {
  attachmentId: string & tags.Format<'uuid'>;
  attachmentVersionId: string & tags.Format<'uuid'>;
}): Promise<void> {
  const { attachmentId, attachmentVersionId } = props;

  // Step 1: Fetch the version by id (ensure not already deleted)
  const version = await MyGlobal.prisma.shopping_mall_ai_attachment_versions.findUnique({
    where: { id: attachmentVersionId },
    select: { id: true, deleted: true, attachment_id: true },
  });
  if (!version) throw new Error("Attachment version not found");
  if (version.deleted) throw new Error("Attachment version already deleted");
  // Step 2: Fetch parent attachment (ensure not under legal hold)
  // Always fetch by provided attachmentId for strictness
  const attachment = await MyGlobal.prisma.shopping_mall_ai_attachments.findUnique({
    where: { id: attachmentId },
    select: { id: true, legal_hold: true },
  });
  if (!attachment) throw new Error("Attachment not found for version");
  if (attachment.legal_hold) throw new Error("Cannot delete version: legal_hold in effect");
  // Step 3: Soft-delete the attachment version (set deleted=true)
  await MyGlobal.prisma.shopping_mall_ai_attachment_versions.update({
    where: { id: attachmentVersionId },
    data: { deleted: true },
  });
  // TODO: In a production system, emit an immutable audit log of the deletion
  return;
}

