/**
 * Validates a customer JWT token, ensuring it is genuine, unexpired,
 * and represents an active customer account (status = 'active') as stored in
 * shopping_mall_ai_customers. Does not return profile data or perform further
 * permission checks. Stateless; read-only.
 *
 * Used to confirm authentication persistence, session validity, and mobile/web
 * client auth checks. All failure cases and errors are generic — never leak
 * sensitive details.
 *
 * @param props - Request body with the JWT token to validate.
 * @param props.body - The JWT string for authentication validation.
 * @returns Token validation result: isValid, status string, userId (uuid), exp.
 * @throws {Error} Never throws user-visible errors; always returns DTO for all
 * error conditions.
 */
export async function post__auth_customer_validate(
  props: { body: IShoppingMallAiCustomer.ValidateToken }
): Promise<IShoppingMallAiCustomer.ValidateResult> {
  let isValid = false;
  let userId = '00000000-0000-0000-0000-000000000000' as string & tags.Format<'uuid'>;
  let status = 'invalid';
  let exp = 0 as number & tags.Type<'int32'>;
  try {
    // Parse JWT token - only basic safe logic (not full crypto validation)
    const parts = props.body.jwt.split('.');
    if (parts.length !== 3) throw new Error('Malformed token');
    // atob variant: browser and node safe
    const decode = (str: string) =>
      typeof Buffer !== 'undefined'
        ? Buffer.from(str, 'base64').toString('utf8')
        : atob(str);
    const payload = JSON.parse(decode(parts[1]));
    if (typeof payload !== 'object' || payload === null) throw new Error('Invalid JWT payload');
    if (typeof payload.sub !== 'string' || typeof payload.exp !== 'number') throw new Error('Invalid JWT claims');
    exp = payload.exp as number & tags.Type<'int32'>;
    userId = payload.sub as string & tags.Format<'uuid'>;
    // Validate expiration (exp is in seconds)
    if (Math.floor(Date.now() / 1000) > payload.exp) throw new Error('Token expired');
    // Validate user in DB
    const customer = await MyGlobal.prisma.shopping_mall_ai_customers.findUnique({
      where: { id: payload.sub },
      select: { id: true, status: true, deleted_at: true },
    });
    if (!customer || customer.status !== 'active' || customer.deleted_at) {
      throw new Error('Inactive or deleted');
    }
    isValid = true;
    status = customer.status;
  } catch {
    isValid = false;
    userId = '00000000-0000-0000-0000-000000000000' as string & tags.Format<'uuid'>;
    status = 'invalid';
    exp = 0 as number & tags.Type<'int32'>;
  }
  return {
    isValid,
    status,
    userId,
    exp,
  };
}

