export async function put__shoppingMallAi_administrator_attachments_$attachmentId(props: {
  attachmentId: string & tags.Format<'uuid'>;
  body: IShoppingMallAiAttachment.IUpdate;
}): Promise<IShoppingMallAiAttachment> {
  const { attachmentId, body } = props;

  // 1. 소프트 삭제 제외 + ID로 첨부파일 로드 (없으면 예외)
  const attachment = await MyGlobal.prisma.shopping_mall_ai_attachments.findFirst({
