/**
 * Soft-delete an attachment record by ID for compliance, privacy, and lifecycle management. Legal hold enforcement applies.
 *
 * This endpoint marks the shopping_mall_ai_attachments record as deleted (soft delete) if:
 * - The attachment exists
 * - The attachment is not already deleted
 * - The attachment is not under legal hold ("legal_hold" flag is false)
 *
 * If the attachment does not exist, is already deleted, or is under legal hold, an error is thrown.
 *
 * @param props - Request properties
 * @param props.attachmentId - Unique identifier of the attachment (UUID)
 * @returns void (no response body)
 * @throws {Error} When the attachment does not exist, is already deleted, or is under legal hold
 */
export async function delete__shoppingMallAi_administrator_attachments_$attachmentId(
  props: { attachmentId: string & tags.Format<'uuid'> }
): Promise<void> {
  const { attachmentId } = props;
  // Fetch the attachment by primary key
  const attachment = await MyGlobal.prisma.shopping_mall_ai_attachments.findUniqueOrThrow({
    where: { id: attachmentId },
    select: {
      id: true,
      deleted: true,
      legal_hold: true,
    },
  });

  // If the attachment is already deleted, block further soft-deletion
  if (attachment.deleted) {
    throw new Error('Attachment already deleted');
  }

  // If the attachment is under legal hold, deletion is not permitted
  if (attachment.legal_hold) {
    throw new Error('Attachment is under legal hold and cannot be deleted');
  }

  // Perform soft-delete: set deleted=true and deleted_at=now
  await MyGlobal.prisma.shopping_mall_ai_attachments.update({
    where: { id: attachmentId },
    data: {
      deleted: true,
      deleted_at: toISOStringSafe(new Date()),
    },
  });
}

