  // Build dynamic where clause inline for safe type inference
  const where = {
    attachment_id: attachmentId,
    ...(version_number !== undefined && version_number !== null && { version_number }),
    ...(modified_by_id !== undefined && modified_by_id !== null && { modified_by_id }),
