        attachment_id: true,
        version_number: true,
        file_uri: true,
        file_size: true,
        diff_comment: true,
        deleted: true,
        created_at: true,
      },
    }),
    MyGlobal.prisma.shopping_mall_ai_attachment_versions.count({ where }),
  ]);

  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
