/**
 * Secure password hashing for registration/signup using Web Crypto API.
 * Uses PBKDF2/crypto.subtle or browser-compatible implementation.
 * NEVER use Node-only libraries!
 * @param password - plain password
 * @returns hashed password (as hex string)
 */
async function hashPasswordWebCrypto(password: string): Promise<string> {
  const encoder = new TextEncoder();
  const salt = crypto.getRandomValues(new Uint8Array(16));
  const keyMaterial = await crypto.subtle.importKey(
    "raw",
    encoder.encode(password),
    { name: "PBKDF2" },
    false,
    ["deriveBits"]
  );
  const derivedBits = await crypto.subtle.deriveBits(
    {
      name: "PBKDF2",
      salt,
      iterations: 100_000,
      hash: "SHA-256",
    },
    keyMaterial,
    256
  );
  // Concatenate salt+hash (common pattern)
  const result = new Uint8Array(salt.length + derivedBits.byteLength / 8);
  result.set(salt, 0);
  result.set(new Uint8Array(derivedBits), salt.length);
  // Convert to hex string
  return Array.from(result)
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("");
}

/**
