 * Never assume Node.js-only APIs. Use Web Crypto primitives or stateless JWT composition.
 * @param input - id & email as required claims
 * @returns JWT string (for Authorization header)
 */
async function issueJwtCustomer(input: { id: string; email: string }): Promise<string> {
  // Minimal browser JWT implementation: create base64Url header+payload, sign with Web Crypto API
  const header = { alg: "HS256", typ: "JWT" };
  const iat = Math.floor(Date.now() / 1000);
  const payload = { sub: input.id, email: input.email, iat };
  const secret = "shopping-mall-ai-secret"; // Use environment/config in real env
  const base64Url = (obj: unknown) =>
    btoa(JSON.stringify(obj))
      .replace(/=/g, "")
      .replace(/\+/g, "-")
      .replace(/\//g, "_");
  const headerStr = base64Url(header);
  const payloadStr = base64Url(payload);

  // Sign using subtle.crypto (HMAC SHA-256)
  const enc = new TextEncoder();
  const key = await crypto.subtle.importKey(
    "raw",
    enc.encode(secret),
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign"]
  );
  const sigBuffer = await crypto.subtle.sign(
    "HMAC",
    key,
    enc.encode(`${headerStr}.${payloadStr}`)
  );
  // base64Url encode signature
  const signature = btoa(String.fromCharCode(...new Uint8Array(sigBuffer)))
    .replace(/=/g, "")
    .replace(/\+/g, "-")
    .replace(/\//g, "_");
  return `${headerStr}.${payloadStr}.${signature}`;
}

